(6387, 'POST', '/api/upload/save_music', '{"fileId":"金海心-阳光下的星星.mp3-11343928-2de4d66","metadata":{"title":"阳光下的星星","artist":"金海心","album":"独立日","genre":"Pop","duration":"","release_date":"2006-01-11","language":"中文","tags":["青春"],"mood":"Happy","lyrics":[{"time":14.58,"text":"暖暖阳光懒懒爬进窗"},{"time":20.99,"text":"悠悠微醺淡淡咖啡香"},{"time":27.2,"text":"恍然你又在身旁"},{"time":30.56,"text":"笑容星一样明亮"},{"time":33.9,"text":"打开故事书翻到下一页"},{"time":40.25,"text":"你说云落泪了风会吹干它"},{"time":46.87,"text":"我问风叹息又怎么安慰呢"},{"time":53.56,"text":"你只笑笑不回答"},{"time":56.68,"text":"说小姑娘别犯傻"},{"time":59.89,"text":"窗外天空晴朗"},{"time":66.65,"text":"只想抱着你的背脊不想放"},{"time":73.02,"text":"为何美的东西总叫人感伤"},{"time":79.35,"text":"只怕你每次转身"},{"time":84.05,"text":"Hey~"},{"time":86.49,"text":"我会以为看见明天的艳阳"},{"time":93.23,"text":"暖暖阳光懒懒爬进窗"},{"time":99.75,"text":"悠悠微醺淡淡咖啡香"},{"time":106.11,"text":"恍然你又在身旁"},{"time":108.92,"text":"笑容星一样明亮"},{"time":112.75,"text":"打开故事书翻到下一页"},{"time":119.09,"text":"你说云落泪了风会吹干它"},{"time":125.57,"text":"我问风叹息又怎么安慰呢"},{"time":132.06,"text":"你只笑笑不回答"},{"time":135.26,"text":"说小姑娘别犯傻"},{"time":138.67,"text":"窗外天空晴朗"},{"time":145.45,"text":"也许云落泪了风会吹干它"},{"time":151.94,"text":"可是风叹息又怎么安慰呢"},{"time":158.48,"text":"你说就随他去吧"},{"time":165.85,"text":"叫我如何放得下"},{"time":172.86,"text":"候鸟会不会停留"},{"time":176.36,"text":"一生算不算太久"},{"time":179.65,"text":"未来有没有尽头"},{"time":182.45,"text":"够不够"},{"time":183.69,"text":"带~我~走"},{"time":186.67,"text":"候鸟该不该停留"},{"time":189.67,"text":"未来它有没有尽头"},{"time":198.44,"text":"如果爱上你只是一个梦境"},{"time":204.64,"text":"醒来后又该如何重新睡去"},{"time":211.66,"text":"如果失去记忆"},{"time":215.48,"text":"Oh~"},{"time":219.8,"text":"能否再一见钟情"},{"time":225.63,"text":"能否再一见钟情"},{"time":236.51,"text":"能否再一见钟情"}],"cover":"/cover_files/金海心-阳光下的星星.mp3-11343928-2de4d66/金海心-阳光下的星星.mp3-11343928-2de4d66.jpg","mp3":"/music_files/金海心-阳光下的星星.mp3-11343928-2de4d66/金海心-阳光下的星星.mp3-11343928-2de4d66.mp3","id":11,"created_at":"2025-08-04T12:37:37.000Z","updated_at":"2025-08-04T12:37:37.000Z"}}', NULL, NULL, 201, 81, '2025-08-04 12:37:38', '{}', ''),
