(11397, 'POST', '/api/upload/save_music', '{"fileId":"高橋優 - ヤキモチ.mp3-12608051-2bdbbb05","metadata":{"title":"吃醋（ヤキモチ）","artist":"高桥优","album":"今、そこにある明灭と群生","genre":"Pop","duration":"","release_date":"2014-06-12","language":"中文","tags":["起风了"],"mood":"Romantic","lyrics":[{"time":0.016,"text":"ヤキモチ - 高橋優"},{"time":2.035,"text":"词：高橋優"},{"time":3.047,"text":"曲：高橋優"},{"time":28.033,"text":"君が前に付き合っていた人のこと"},{"time":34.064,"text":"僕に打ち明けてくれたとき"},{"time":40.082,"text":"素直に聴いてあげられずに"},{"time":46.02,"text":"寂しい思いをさせてしまったね"},{"time":51.076,"text":"すぐにヤキモチ焼くのが"},{"time":56.046,"text":"僕の悪い癖だって"},{"time":57.096,"text":"分かっていた筈なのに"},{"time":64.013,"text":"自分勝手な想いが残酷な"},{"time":70.033,"text":"言葉になって君を傷付けてた"},{"time":77.076,"text":"一緒に居られるだけで"},{"time":81.073,"text":"手と手を重ね合えるだけで"},{"time":86.074,"text":"良かったね"},{"time":89.084,"text":"大切な事ほど"},{"time":93.058,"text":"見慣れた場所で"},{"time":96.001,"text":"輝くのかもしれない"},{"time":102.024,"text":"君を強く抱きしめたい"},{"time":118.076,"text":"自分のためだけに生きている人が"},{"time":125.01,"text":"集められたようなこの街で"},{"time":131.013,"text":"誰かを心から想える"},{"time":136.06,"text":"幸せをいつまでも忘れたくない"},{"time":142.007,"text":"すぐにヤキモチ焼く"},{"time":145.062,"text":"とこも好きだよってからかって"},{"time":149.053,"text":"笑う君に甘えていた"},{"time":154.057,"text":"愛していることを"},{"time":158.004,"text":"言葉以外の方法で"},{"time":162.004,"text":"今すぐに伝えたい"},{"time":167.097,"text":"微笑んでくれた顔も"},{"time":172.015,"text":"怒った顔も愛しくて"},{"time":176.04,"text":"仕方なかったよ"},{"time":180.029,"text":"打ち明けてくれた過去も"},{"time":184.058,"text":"二人が見た青空も忘れない"},{"time":217.075,"text":"一緒に居られるだけで"},{"time":221.098,"text":"手と手を重ね合えるだけで"},{"time":226.092,"text":"良かったね"},{"time":230.018,"text":"大切な事ほど"},{"time":233.054,"text":"見慣れた場所で"},{"time":236.029,"text":"輝くのかもしれない"},{"time":242.071,"text":"微笑んでくれた顔も"},{"time":246.095,"text":"怒った顔も愛しくて"},{"time":251.022,"text":"仕方なかったよ"},{"time":255.009,"text":"君の事が好きだよ"},{"time":259.008,"text":"これからもずっと"},{"time":262.013,"text":"君を抱きしめたい"},{"time":267.049,"text":"君を強く抱きしめた"}],"cover":"/cover_files/高橋優 - ヤキモチ.mp3-12608051-2bdbbb05/高橋優 - ヤキモチ.mp3-12608051-2bdbbb05.jpg","mp3":"/music_files/高橋優 - ヤキモチ.mp3-12608051-2bdbbb05/高橋優 - ヤキモチ.mp3-12608051-2bdbbb05.mp3","id":12,"created_at":"2025-08-05T00:56:11.000Z","updated_at":"2025-08-05T00:56:11.000Z"}}', NULL, NULL, 201, 77, '2025-08-05 00:56:11', '{}', ''),
